import * as React from "react"

function CardAnimate({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-animate"
      className={className}
      {...props}
    >
      <div className="relative p-8 overflow-hidden rounded-xl min-h-28 max-w-96 shadow h-fit w-full dark950 dark100 transition-all duration-200 border border-cool-300 dark700 group hover">

        <div className="absolute inset-0 opacity-0 group-hover100 transition-opacity duration-300 -z-10 blur-xl">
          <div className="absolute w-20 h-20 bg-gradient-to-r from-purple-400 via-pink-500 to-red-500 rounded-full transform -translate-x-1/2 -translate-y-1/2 pointer-events-none mix-blend-soft-light transition-all duration-100"
           style="top: var(--mouse-y); left: var(--mouse-x);"></div>
        </div>


        <h2 className="text-xl font-bold mb-2 relative">Título de la tarjeta</h2>
        <p className="text-gray-700 relative">Este es el contenido de la tarjeta.</p>
      </div>


    </div>
  )
}

export { CardAnimate }
